// Bridges legacy INDUSTRY_CASES into the sim engine and adds per-industry
// stakeholders + recommended delivery approach. Kept thin on purpose — deeper
// case content is generated by the generator based on this metadata.

import { INDUSTRY_CASES, getIndustry } from "@/lib/sim/legacy/industries";
import { customerPortalStakeholders } from "./casepacks/customer-portal";
import type { DeliveryApproach, IndustryCaseRef, Stakeholder } from "./types";


const APPROACH_BY_ID: Record<string, DeliveryApproach> = {
  semiconductor: "Predictive",
  automotive: "Hybrid",
  aviation: "Predictive",
  "supply-chain": "Hybrid",
  engineering: "Predictive",
  construction: "Predictive",
  software: "Agile",
  healthcare: "Hybrid",
  pharma: "Predictive",
  energy: "Predictive",
  banking: "Hybrid",
  aerospace: "Hybrid",
  manufacturing: "Hybrid",
  retail: "Agile",
  gov: "Hybrid",
};

export function getCaseRef(caseId: string): IndustryCaseRef {
  const c = getIndustry(caseId);
  return { ...c, recommendedApproach: APPROACH_BY_ID[c.id] ?? "Hybrid" };
}

export function listCases(): IndustryCaseRef[] {
  return INDUSTRY_CASES.map((c) => ({
    ...c,
    recommendedApproach: APPROACH_BY_ID[c.id] ?? "Hybrid",
  }));
}

