// Industry-specific role tweaks — override role/priority text only.
const ROLE_OVERRIDES: Record<string, Partial<Record<string, Partial<Stakeholder>>>> = {
  aviation: { "risk-officer": { role: "FAA Liaison", priorities: ["STC approval", "Airworthiness", "C-check alignment"] } },
  pharma: { "risk-officer": { role: "GCP / Regulatory Lead", priorities: ["GCP compliance", "IRB", "Data integrity"] } },
  banking: { "risk-officer": { role: "Chief Risk Officer", priorities: ["Regulator concurrence", "SOX", "Reconciliation"] } },
  healthcare: { "risk-officer": { role: "HIPAA / CMIO Delegate", priorities: ["HIPAA", "Clinician safety", "Downtime"] } },
  gov: { "risk-officer": { role: "Federal Certification Lead", priorities: ["MECT/CMS certification", "WCAG 2.2", "Auditability"] } },
  aerospace: { "risk-officer": { role: "ITAR / Export Control", priorities: ["ITAR", "Debris coordination", "Launch licensing"] } },
  construction: { "vendor": { role: "General Contractor", priorities: ["Trade sequencing", "Change orders", "Weather"] } },
  energy: { "risk-officer": { role: "FERC / DOE Liaison", priorities: ["FERC/DOE permits", "HSE", "Turnaround safety"] } },
};

export function stakeholdersFor(caseId: string): Stakeholder[] {
  if (caseId === "software") {
    // Customer Portal case ships with a full cross-functional cast.
    // Import lazily to avoid a circular import with the generator.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { customerPortalStakeholders } = require("./casepacks/customer-portal") as typeof import("./casepacks/customer-portal");
    return customerPortalStakeholders;
  }
  const overrides = ROLE_OVERRIDES[caseId] ?? {};
  return BASE_STAKES.map((s) => ({ ...s, ...(overrides[s.id] ?? {}) }));
}

